    constructor(location) {
        this.location = location;
        this.isOn = false;
        this.soilMoistureLevel = 0;
    }

    checkWeatherForecast() {
        // Simulate checking weather forecast
        const forecast = sunny; // This would be fetched from a weather API
        return forecast;
    }

    measureSoilMoisture() {
        // Simulate measuring soil moisture
        this.soilMoistureLevel = Math.random(); // This would be fetched from a soil moisture sensor
    }

    decideWatering() {
        this.measureSoilMoisture();
        const forecast = this.checkWeatherForecast();

        if (this.soilMoistureLevel < 0.3 && forecast !== rainy) {
            this.turnOn();
        } else {
            this.turnOff();
        }
    }

    turnOn() {
        this.isOn = true;
        console.log(Sprinkler is ON);
    }

    turnOff() {
        this.isOn = false;
        console.log(Sprinkler is OFF);
    }
}

