// The code below demonstrates a simple function to check if a number is even or odd.

function checkEvenOdd(number) {
    if (number % 2 === 0) {
        return Even;
    } else {
        return Odd;
    }
}

// Example usage:
console.log(checkEvenOdd(4)); // Output: Even
console.log(checkEvenOdd(7)); // Output: Odd

